37	// ------------------------------------------------------------------ Mobile hotspot detection
38	// Detects mobile hotspots by common SSID patterns
39	bool isMobileHotspotSSID(const String& ssid) {
40	  String upper = ssid;
41	  upper.toUpperCase();
42	  // Common mobile hotspot patterns
43	  return ssid.startsWith("Redmi") || ssid.startsWith("Xiaomi") ||
44	         ssid.startsWith("iPhone") || ssid.startsWith("iPad") ||
45	         ssid.startsWith("Android") || ssid.startsWith("Motorola") ||
46	         ssid.startsWith("Huawei") || ssid.startsWith("HUAWEI") ||
47	         ssid.startsWith("Samsung") || ssid.startsWith("ONEPLUS") ||
48	         ssid.startsWith("OPPO") || ssid.startsWith("Vivo") ||
49	         upper.startsWith("MOBILE") || upper.startsWith("HOTSPOT") ||
50	         upper.startsWith("热点") || ssid.indexOf("K60") != -1 ||
51	         ssid.indexOf("K50") != -1 || ssid.indexOf("K30") != -1;
52	}
