161	// Helper function to try connecting to a specific network
162	bool tryConnectToWifi(const String& ssid, const String& password) {
163	  WiFi.disconnect(true);  // true = also clear saved AP config
164	  delay(200);
165	
166	  if (password.length() > 0) {
167	    WiFi.begin(ssid.c_str(), password.c_str());
168	  } else {
169	    WiFi.begin(ssid.c_str());
170	  }
171	
172	  uint32_t t0 = millis();
173	  // Extended timeout to 8s: ESP32-C3 association can take 4-6s on congested channels
174	  while (WiFi.status() != WL_CONNECTED && millis() - t0 < 8000) {
175	    delay(200);
176	  }
177	
178	  bool connected = (WiFi.status() == WL_CONNECTED);
179	  if (connected) {
180	    WiFi.setAutoReconnect(true);
181	  }
182	
183	  return connected;
184	}
