245	static bool fetchQuotes() {
246	  if (WiFi.status() != WL_CONNECTED) return false;
247	  WiFiClientSecure cli;
248	  cli.setInsecure();
249	  HTTPClient http;
250	  http.setTimeout(10000);
251	  http.setFollowRedirects(HTTPC_STRICT_FOLLOW_REDIRECTS);
252	  if (!http.begin(cli, API_URL)) return false;
253	  int code = http.GET();
254	  if (code != 200) {
255	    Serial.printf("[api] HTTP %d\n", code);
256	    http.end();
257	    return false;
258	  }
259	  String body = http.getString();
260	  http.end();
261	  JsonDocument doc;
262	  if (deserializeJson(doc, body)) return false;
263	
264	  int added = 0;
265	  auto parseOne = [&](JsonVariantConst o) {
266	    Quote q;
267	    q.idx = jstr(o, "idx");
268	    q.content = jstr(o, "content", "main_content");
269	    if (q.content.length() == 0) return;
270	    q.context = jstr(o, "context");
271	    q.date = jstr(o, "date", "effectiveDate");
272	    q.specific = jstr(o, "specific", "specificName");
273	    q.container = jstr(o, "container", "containerName");
274	    q.cat = jstr(o, "cat", "category");
275	    JsonVariantConst tg = o["tags"].isNull() ? o["hashtagThemes"] : o["tags"];
276	    if (tg.is<JsonArrayConst>()) {
277	      for (JsonVariantConst t : tg.as<JsonArrayConst>()) {
278	        String s = t.as<String>();
279	        if (!s.startsWith("#")) s = "#" + s;
280	        q.tags.push_back(s);
281	      }
282	    }
283	    // Prevent duplicate quote entries in RAM
284	    for (const auto& existing : quotes) {
285	      if (existing.idx == q.idx) return;
286	    }
287	    quotes.push_back(q);
288	    added++;
289	  };
290	
291	  if (doc.is<JsonArray>()) for (JsonVariantConst o : doc.as<JsonArray>()) parseOne(o);
292	  else parseOne(doc.as<JsonVariantConst>());
293	
294	  // Purge temporary offline standby card once genuine cloud quotes are received
295	  if (added > 0 && !quotes.empty() && quotes[0].idx == "!") {
296	    quotes.erase(quotes.begin());
297	  }
298	
299	  // Limit pool size in RAM to max 20 quotes to bound heap consumption
300	  while (quotes.size() > 20) {
301	    quotes.erase(quotes.begin());
302	  }
303	
304	  Serial.printf("[api] Cloudflare stream: +%d quotes (RAM pool: %d)\n", added, (int)quotes.size());
305	  return added > 0;
306	}
