308	// ------------------------------------------------------------------ utf-8
309	static std::u16string u8to16(const String& s) {
310	  std::u16string o;
311	  const uint8_t* p = (const uint8_t*)s.c_str();
312	  size_t n = s.length();
313	  for (size_t i = 0; i < n;) {
314	    uint8_t c = p[i];
315	    uint32_t cp;
316	    int len;
317	    if (c < 0x80) { cp = c; len = 1; }
318	    else if ((c >> 5) == 6) { cp = c & 0x1F; len = 2; }
319	    else if ((c >> 4) == 14) { cp = c & 0x0F; len = 3; }
320	    else if ((c >> 3) == 30) { cp = c & 0x07; len = 4; }
321	    else { i++; continue; }
322	    if (i + len > n) break;
323	    for (int k = 1; k < len; k++) cp = (cp << 6) | (p[i + k] & 0x3F);
324	    i += len;
325	    o.push_back(cp > 0xFFFF ? u'?' : (char16_t)cp);
326	  }
327	  return o;
328	}
