334	static bool isWS(char16_t c) { return c == ' ' || c == '\t' || c == '\r' || c == 0xA0; }
335	
336	static void tokenize(const std::u16string& s, std::vector<std::u16string>& tok) {
337	  std::u16string w;
338	  auto flush = [&]() { if (!w.empty()) { tok.push_back(w); w.clear(); } };
339	  for (char16_t c : s) {
340	    if (c == '\n') { flush(); tok.push_back(u"\n"); }
341	    else if (isWS(c)) flush();
342	    else w.push_back(c);
343	  }
344	  flush();
345	}
346	
347	static std::u16string trim16(const std::u16string& s) {
348	  size_t a = 0, b = s.size();
349	  while (a < b && (isWS(s[a]) || s[a] == '\n')) a++;
350	  while (b > a && (isWS(s[b - 1]) || s[b - 1] == '\n')) b--;
351	  return s.substr(a, b - a);
352	}
