359	static std::vector<Page> buildPages(const Quote& q) {
360	  std::vector<Page> pages;
361	  std::u16string content = trim16(u8to16(q.content));
362	  if (content.empty()) { pages.push_back({{{u"", false}}, false}); return pages; }
363	  std::vector<std::u16string> tok;
364	  tokenize(content, tok);
365	  bool writing = isWriting(q.cat);
366	  size_t ti = 0;
367	  int pageNum = 0;
368	  while (ti < tok.size()) {
369	    pageNum++;
370	    bool first = pageNum == 1;
371	    std::vector<std::u16string> pl;
372	    for (int ln = 1; ln <= MAX_LINES && ti < tok.size(); ln++) {
373	      int budget = MAX_CHARS;
374	      if (first && ln == 1) budget = MAX_CHARS - 1;
375	      if (ln == MAX_LINES) budget = MAX_CHARS - 4;
376	      std::u16string cur;
377	      while (ti < tok.size()) {
378	        const std::u16string& nt = tok[ti];
379	        if (nt == u"\n") { ti++; break; }
380	        if (cur.empty()) { cur = nt; ti++; }
381	        else if ((int)(cur.size() + 1 + nt.size()) <= budget) { cur += u" "; cur += nt; ti++; }
382	        else break;
383	      }
384	      pl.push_back(cur);
385	    }
386	    size_t la = ti;
387	    while (la < tok.size() && tok[la] == u"\n") la++;
388	    bool more = la < tok.size();
389	    if (first && !pl.empty()) pl[0] = u"\u201C" + pl[0];
390	    if (more) pl.back() += u"...";
391	    else pl.back() += u"\u201D";
392	    Page pg; pg.ctx = false;
393	    for (size_t i = 0; i < pl.size(); i++) {
394	      bool terminal = !more && i == pl.size() - 1;
395	      bool just = writing && !terminal && pl[i].find(u' ') != std::u16string::npos;
396	      if (!trim16(pl[i]).empty()) pg.lines.push_back({pl[i], just});
397	    }
398	    pages.push_back(pg);
399	  }
400	  // context pages
401	  if (q.context.length() > 0) {
402	    std::vector<std::u16string> cw;
403	    tokenize(u8to16(q.context), cw);
404	    size_t ci = 0;
405	    bool firstCtx = true;
406	    while (ci < cw.size()) {
407	      std::vector<std::u16string> cl;
408	      for (int l = 1; l <= MAX_LINES && ci < cw.size(); l++) {
409	        int budget = (l == MAX_LINES) ? MAX_CHARS - 4 : MAX_CHARS;
410	        std::u16string cur;
411	        if (firstCtx && l == 1) { cur = u"[Note] "; firstCtx = false; }
412	        while (ci < cw.size()) {
413	          if (cw[ci] == u"\n") { ci++; continue; }
414	          if (cur.empty()) { cur = cw[ci]; ci++; }
415	          else if ((int)(cur.size() + 1 + cw[ci].size()) <= budget || cur == u"[Note] ") {
416	            if (cur != u"[Note] ") cur += u" ";
417	            cur += cw[ci]; ci++;
418	          } else break;
419	        }
420	        cl.push_back(cur);
421	      }
422	      if (ci < cw.size() && !cl.empty()) cl.back() += u"...";
423	      Page pg; pg.ctx = true;
424	      for (auto& s : cl) {
425	        if (!trim16(s).empty()) pg.lines.push_back({s, false});
426	      }
427	      if (!pg.lines.empty()) pages.push_back(pg);
428	    }
429	  }
430	  return pages;
431	}
