442	static uint16_t hsl565(float h, float s, float l) {
443	  h = fmodf(h, 360.f); if (h < 0) h += 360.f;
444	  float c = (1 - fabsf(2 * l - 1)) * s;
445	  float x = c * (1 - fabsf(fmodf(h / 60.f, 2) - 1));
446	  float m = l - c / 2, r = 0, g = 0, b = 0;
447	  if (h < 60) { r = c; g = x; }
448	  else if (h < 120) { r = x; g = c; }
449	  else if (h < 180) { g = c; b = x; }
450	  else if (h < 240) { g = x; b = c; }
451	  else if (h < 300) { r = x; b = c; }
452	  else { r = c; b = x; }
453	  // Boost minimum lightness to prevent low-contrast grays that blur on black
454	  float minLightness = 0.55f;
455	  float boostedL = m + (1.0f - m) * minLightness;
456	  return rgb565((r + boostedL) * 255, (g + boostedL) * 255, (b + boostedL) * 255);
457	}
