472	// Ensure tag background colors have sufficient contrast on black
473	static uint16_t ensureContrast(uint16_t col, uint16_t bg = 0x0000) {
474	  uint8_t r = (col >> 11) & 0x1F;
475	  uint8_t g = (col >> 5) & 0x3F;
476	  uint8_t b = col & 0x1F;
477	  r = (r << 3) | (r >> 2);
478	  g = (g << 2) | (g >> 4);
479	  b = (b << 3) | (b >> 2);
480	  int luminance = (r * 299 + g * 587 + b * 114) / 1000;
481	  if (luminance < 80) {
482	    // Boost color to be readable on black
483	    float boost = 80.0f / max(luminance, 1);
484	    r = min(255, (int)(r * boost));
485	    g = min(255, (int)(g * boost));
486	    b = min(255, (int)(b * boost));
487	  }
488	  return rgb565(r, g, b);
489	}
