497	static void drawHeader(const Quote& q, bool busy) {
498	  cv.h = HDR_H;
499	  cv.fill(C_BLACK);
500	  cv.rect(0, HDR_H - 1, SW, 1, C_RULE);
501	  const int base = 14;
502	  std::u16string date = u8to16(q.date.length() ? q.date : String("—"));
503	  int dateW = fSB10.adv * (int)date.size();
504	  int labelW = fSB10.adv * 5;
505	  int rightW = labelW + 4 + dateW;
506	  int rx = SW - 12 - rightW;
507	  cv.text(fSB10, rx, base, u"Date:", C_DIM);
508	  cv.text(fSB10, rx + labelW + 4, base, date, C_GHOST);
509	  int x = 12;
510	  if (busy) {
511	    cv.text(fSB10, x, base, u"// Receiving prescript...", C_GHOST);
512	  } else {
513	    std::u16string idx = u"#" + u8to16(q.idx);
514	    x += cv.text(fBD13, x, base, idx, C_GHOST) + 4;
515	    x += cv.text(fSB10, x, base, u"~", C_SEP) + 4;
516	    std::u16string title = u8to16(q.specific);
517	    int avail = rx - 8 - x;
518	    int maxCh = avail / fSB10.adv;
519	    if ((int)title.size() > maxCh && maxCh > 1) title = title.substr(0, maxCh - 1) + u"\u2026";
520	    cv.text(fSB10, x, base, title, C_TITLE, avail);
521	  }
522	  push(0, HDR_H);
523	}
