525	static void drawFooter(const Quote& q, int seed = 0) {
526	  cv.h = FTR_H;
527	  cv.fill(C_BLACK);
528	  cv.rect(0, 0, SW, 1, C_RULE);
529	  uint16_t accent = accentFor(q);
530	  const int base = 15;
531	  std::u16string cont = u8to16(q.container);
532	  int contMax = 150 / fSB10.adv;
533	  if ((int)cont.size() > contMax) cont = cont.substr(0, contMax - 1) + u"\u2026";
534	  int contW = fSB10.adv * (int)cont.size();
535	  int cx = SW - 12 - contW;
536	  cv.text(fBD13, cx, base, cont, accent);
537	  int x = 12;
538	  for (size_t i = 0; i < q.tags.size(); i++) {
539	    std::u16string t = u8to16(q.tags[i]);
540	    int w = fSB9.adv * (int)t.size() + 10 + 2;
541	    if (x + w > cx - 8) break;
542	    float hue = tagHue(q.tags[i], (int)i) + seed;
543	    uint16_t tcol = ensureContrast(hsl565(hue, 0.90f, 0.80f));
544	    uint16_t bg = hsl565(hue, 0.65f, 0.15f);  // Slightly lighter bg
545	    uint16_t bd = mix565(C_BLACK, ensureContrast(hsl565(hue, 0.75f, 0.50f)), 140);
546	    const int y0 = 4, hh = 15;
547	    cv.rect(x, y0, w, hh, bd);
548	    cv.rect(x + 1, y0 + 1, w - 2, hh - 2, bg);
549	    cv.b[y0 * cv.w + x] = C_BLACK; cv.b[y0 * cv.w + x + w - 1] = C_BLACK;
550	    cv.b[(y0 + hh - 1) * cv.w + x] = C_BLACK; cv.b[(y0 + hh - 1) * cv.w + x + w - 1] = C_BLACK;
551	    cv.text(fSB9, x + 6, y0 + 11, t, tcol);
552	    x += w + 4;
553	  }
554	  push(SH - FTR_H, FTR_H);
555	}
