570	static void drawBodyLineFinal(const Line& ln, int y, bool ctx, uint16_t accent) {
571	  cv.h = 20;
572	  cv.fill(ctx ? C_BOXBG : C_BLACK);
573	  const VFont& fn = fBD13;
574	  int base = (20 - (fn.ascent + fn.descent)) / 2 + fn.ascent;
575	  int cellW = fn.adv;
576	  int x0 = ctx ? 16 : 16;
577	  if (ctx) cv.rect(8, 0, 3, 20, accent);
578	  const std::u16string& s = ln.t;
579	  std::vector<int> xs(s.size());
580	  int spaces = 0;
581	  for (char16_t c : s) if (c == ' ') spaces++;
582	  if (ln.just && spaces > 0) {
583	    int W = MAX_CHARS * cellW;
584	    int gap = W - (int)(s.size() - spaces) * cellW;
585	    int extra = gap - spaces * 0;
586	    int per = extra / spaces, rem = extra % spaces, x = x0, sp = 0;
587	    for (size_t i = 0; i < s.size(); i++) {
588	      xs[i] = x;
589	      if (s[i] == ' ') x += per + (sp++ < rem ? 1 : 0);
590	      else x += cellW;
591	    }
592	  } else {
593	    for (size_t i = 0; i < s.size(); i++) xs[i] = x0 + (int)i * cellW;
594	  }
595	  for (size_t i = 0; i < s.size(); i++) {
596	    char16_t c = s[i];
597	    if (c == ' ') continue;
598	    if (ctx) {
599	      if (i < 6 && s.size() >= 6 && s.substr(0, 6) == u"[Note]") {
600	        cv.drawChar(fBD13, xs[i], base, c, accent, true); // Bilevel 1-bit crisp
601	      } else {
602	        cv.drawChar(fBD13, xs[i], base, c, C_WHITE, true);  // Bilevel 1-bit crisp
603	      }
604	    } else {
605	      if (c == 0x201C || c == 0x201D || c == '.') cv.drawChar(fBD13, xs[i], base, c, accent);
606	      else cv.drawChar(fn, xs[i], base, c, C_WHITE);
607	    }
608	  }
609	  push(y, 20);
610	}
611	
612	static void renderPageFinal(const Page& pg, uint16_t accent) {
613	  clearBody();
614	  int y = bodyTop((int)pg.lines.size());
615	  for (size_t i = 0; i < pg.lines.size(); i++) drawBodyLineFinal(pg.lines[i], y + (int)i * LINE_PITCH, pg.ctx, accent);
616	}
