618	// ------------------------------------------------------------------ entropy animation
619	struct Cell { char16_t target, cur; uint32_t life, nextScr; bool locked; };
620	static Cell grid[MAX_LINES][MAX_CHARS + 8];
621	static int gridLen[MAX_LINES];
622	static const char SCRAMBLE[] = "ABCDEF@HIJ_LM%OPQR^WX#YZa#b+cdefgh*iqrxyz0123456789!$*+=-~?/";
623	static char16_t rndCipher() { return SCRAMBLE[random(sizeof(SCRAMBLE) - 1)]; }
624	
625	// ------------------------------------------------------------------ state
626	static std::vector<Page> pages;
627	static int curPage = 0;
628	static bool animating = false;
629	static uint32_t animStart = 0, lastFrame = 0;
630	static uint32_t nextGapChime = 0xFFFFFFFF; // Absolute ms timestamp of next gap complete chime
631	static uint16_t curAccent = ACCENTS[0];
632	
633	static uint32_t animFrameCount = 0;
634	
635	static void finishAnimation(bool playChime) {
636	  animating = false;
637	  nextGapChime = 0xFFFFFFFF;
638	  Serial.printf("[anim] FINISH at %u ms (%u frames, playChime=%d)\n", millis() - animStart, animFrameCount, playChime);
639	  renderPageFinal(pages[curPage], curAccent);
640	  drawHeader(quotes[curQuote], false);
641	  if (playChime) jqPlay(TRACK_COMPLETE);
642	}
643	
644	static bool renderAnimationFrame(uint32_t el) {
645	  Page& pg = pages[curPage];
646	  bool all = true;
647	  int y = bodyTop((int)pg.lines.size());
648	  const int base = (20 - (fBD13.ascent + fBD13.descent)) / 2 + fBD13.ascent;
649	
650	  for (int r = 0; r < (int)pg.lines.size() && r < MAX_LINES; r++) {
651	    cv.h = 20;
652	    cv.fill(C_BLACK);
653	    for (int c = 0; c < gridLen[r]; c++) {
654	      Cell& ce = grid[r][c];
655	      if (!ce.locked) {
656	        if (el >= ce.life) {
657	          ce.locked = true;
658	          ce.cur = ce.target;
659	        } else {
660	          all = false;
661	          // Active continuous cipher scramble on every frame
662	          ce.cur = rndCipher();
663	        }
664	      }
665	      int x = 16 + c * fBD13.adv;
666	      if (ce.locked) {
667	        if (ce.target == ' ') continue;
668	        if (ce.target == 0x201C || ce.target == 0x201D || ce.target == '.')
669	          cv.drawChar(fBD13, x, base, ce.target, curAccent);
670	        else
671	          cv.drawChar(fBD13, x, base, ce.target, C_WHITE);
672	      } else {
673	        cv.drawChar(fBD13, x, base, ce.cur, C_WHITE);
674	      }
675	    }
676	    push(y + r * LINE_PITCH, 20);
677	  }
678	  return all;
679	}
680	
681	static void showPage(bool animate, bool sound) {
682	  const Quote& q = quotes[curQuote];
683	  curAccent = accentFor(q);
684	  Page& pg = pages[curPage];
685	  drawFooter(q);
686	  if (!animate || pg.ctx) {
687	    animating = false;
688	    nextGapChime = 0xFFFFFFFF;
689	    drawHeader(q, false);
690	    renderPageFinal(pg, curAccent);
691	    if (sound) jqPlay(TRACK_COMPLETE);
692	    return;
693	  }
694	
695	  uint32_t total = max<uint32_t>(900, ENTROPY_MS * 35);
696	  for (int r = 0; r < (int)pg.lines.size() && r < MAX_LINES; r++) {
697	    const std::u16string& s = pg.lines[r].t;
698	    gridLen[r] = min<int>((int)s.size(), MAX_CHARS + 8);
699	    for (int c = 0; c < gridLen[r]; c++)
700	      grid[r][c] = {s[c], rndCipher(), (uint32_t)random(total), (uint32_t)random(40), false};
701	  }
702	  animating = true;
703	  animFrameCount = 0;
704	
705	  // Draw header and clear body while draw_sound plays
706	  drawHeader(q, true);
707	  clearBody();
708	
709	  if (sound) {
710	    // Fire draw_sound, then fill the wait window with live cipher scramble —
711	    // no dead screen: body churns with noise until animation officially begins
712	    jqPlay(TRACK_DRAW);
713	    uint32_t waitEnd = millis() + DRAW_SOUND_DURATION_MS;
714	    while (millis() < waitEnd) {
715	      renderAnimationFrame(0); // elapsed=0 keeps all cells scrambling, none locked
716	      delay(30);
717	    }
718	  }
719	
720	  Serial.printf("[anim] START Quote #%s (total=%u ms)\n", q.idx.c_str(), total);
721	
722	  // Frame 0: initial scramble — no black void
723	  renderAnimationFrame(0);
724	
725	  // Time base starts after draw sound has fully played
726	  animStart = millis();
727	  lastFrame = animStart;
728	
729	  // Gap chimes: complete_sound fires at DRAW_TO_COMPLETE_MS into animation, then every BETWEEN_COMPLETES_MS
730	  nextGapChime = sound ? (animStart + DRAW_TO_COMPLETE_MS) : 0xFFFFFFFF;
731	}
732	
733	static void loadQuote(int idx, bool animate, bool sound) {
734	  curQuote = idx;
735	  pages = buildPages(quotes[curQuote]);
736	  curPage = 0;
737	  g_missingGlyphs = 0;
738	  showPage(animate, sound);
739	  Serial.printf("[quote] #%s pages=%d missingGlyphs=%d heap=%u\n", quotes[curQuote].idx.c_str(),
740	                (int)pages.size(), g_missingGlyphs, ESP.getFreeHeap());
741	}
742	
743	static void abortAndFinishActiveAnimation() {
744	  if (animating) {
745	    animating = false;
746	    nextGapChime = 0xFFFFFFFF;
747	    renderPageFinal(pages[curPage], curAccent);
748	    drawHeader(quotes[curQuote], false);
749	    delay(20);
750	  }
751	}
