753	static uint32_t lastRollTime = 0;
754	static void rollQuote() {
755	  uint32_t now = millis();
756	  if (now - lastRollTime < 400) return; // Debounce rapid multi-clicks
757	  lastRollTime = now;
758	
759	  animating = false;
760	  nextGapChime = 0xFFFFFFFF;
761	
762	  if (quotes.empty()) {
763	    if (WiFi.status() == WL_CONNECTED) {
764	      fetchQuotes();
765	    }
766	    if (quotes.empty()) {
767	      setOfflineStandbyQuote();
768	    }
769	  }
770	
771	  int n = (int)quotes.size(), i = curQuote;
772	  if (n > 1) {
773	    while (i == curQuote) i = random(n);
774	  } else {
775	    i = 0;
776	  }
777	  curQuote = i;
778	  Serial.printf("[roll] Rolling to Quote #%s...\n", quotes[curQuote].idx.c_str());
779	
780	  // Fire draw_sound immediately before animation — jqPlay() already holds 25ms for DAC sync.
781	  // No audio.stop() needed: JQ8900 auto-restarts on a new playTrack() command.
782	  loadQuote(curQuote, true, true);
783	
784	  // Prefetch fresh batch from Cloudflare Worker if RAM pool is running low
785	  if (quotes.size() < 4 && WiFi.status() == WL_CONNECTED) {
786	    fetchQuotes();
787	  }
788	}
789	
790	static uint32_t lastPageTime = 0;
791	static void changePage() {
792	  uint32_t now = millis();
793	  if (now - lastPageTime < 300) return; // Debounce rapid multi-clicks
794	  lastPageTime = now;
795	
796	  // If animating, click FIRST ends animation and reveals full text
797	  if (animating) {
798	    Serial.println("[page] Finishing active animation on click");
799	    abortAndFinishActiveAnimation();
800	    jqPlay(TRACK_COMPLETE);
801	    return;
802	  }
803	  curPage = (curPage + 1) % (int)pages.size();
804	  Serial.printf("[page] Manual turn to Page %d / %d\n", curPage + 1, (int)pages.size());
805	  showPage(true, true);
806	}
807	
808	static void stepAnimation() {
809	  uint32_t now = millis();
810	  uint32_t el = now - animStart;
811	
812	  // Target smooth ~30ms frame pace
813	  if (now - lastFrame < 30) {
814	    vTaskDelay(1);
815	    return;
816	  }
817	  lastFrame = now;
818	  animFrameCount++;
819	
820	  // Gap chime scheduler: fire complete_sound at DRAW_TO_COMPLETE_MS, then every BETWEEN_COMPLETES_MS
821	  if (now >= nextGapChime) {
822	    jqPlay(TRACK_COMPLETE);
823	    nextGapChime = now + BETWEEN_COMPLETES_MS;
824	  }
825	
826	  bool all = renderAnimationFrame(el);
827	  if (all || el >= 2500) finishAnimation(true);
828	  vTaskDelay(1);
829	}
