831	// ------------------------------------------------------------------ boot UI
832	static void splash(const char* l1, const char* l2 = "") {
833	  cv.h = 24;
834	  tft.fillRect(0, 60, SW, 60, C_BLACK);
835	  std::u16string a = u8to16(l1), b = u8to16(l2);
836	  cv.fill(C_BLACK);
837	  cv.text(fSB10, (SW - (int)a.size() * fSB10.adv) / 2, 16, a, C_WHITE);
838	  push(66, 24);
839	  cv.fill(C_BLACK);
840	  cv.text(fRG10, (SW - (int)b.size() * fRG10.adv) / 2, 16, b, C_GHOST);
841	  push(92, 24);
842	}
