844	struct Btn {
845	  uint8_t pin;
846	  bool latched = false;
847	  uint32_t highSince = 0;
848	
849	  bool pressed() {
850	    bool reading = digitalRead(pin);
851	    uint32_t now = millis();
852	
853	    if (reading == LOW) {
854	      highSince = 0;
855	      if (!latched) {
856	        latched = true;
857	        return true; // 0ms instantaneous response on press
858	      }
859	    } else {
860	      if (latched) {
861	        if (highSince == 0) {
862	          highSince = now;
863	        } else if (now - highSince >= 50) {
864	          // Stably released for 50ms, release latch (handles internal ~45k pull-up rise time)
865	          latched = false;
866	          highSince = 0;
867	        }
868	      }
869	    }
870	    return false;
871	  }
872	};
873	static Btn btnRoll = {PIN_BTN_ROLL};
874	static Btn btnRollAlt = {PIN_BTN_ROLL_ALT};
875	static Btn btnScroll = {PIN_BTN_SCROLL};
