877	void setup() {
878	  // Disable hardware brownout detector to prevent nuisance resets during speaker amplifier transients
879	  WRITE_PERI_REG(RTC_CNTL_BROWN_OUT_REG, 0);
880	
881	  Serial.begin(115200);
882	  Serial.setTxTimeoutMs(0); // Never block execution on USB CDC when host is not reading
883	  pinMode(PIN_BTN_ROLL, INPUT_PULLUP);
884	  pinMode(PIN_BTN_ROLL_ALT, INPUT_PULLUP);
885	  pinMode(PIN_BTN_SCROLL, INPUT_PULLUP);
886	  randomSeed(esp_random());
887	
888	  // Initialize audio driver with constant high volume (28/30)
889	  audio.begin(PIN_JQ_TX);
890	  delay(100);
891	  audio.setVolume(JQ_VOLUME_CONSTANT);
892	
893	  // Hardware reset pulse on LCD RST pin
894	  pinMode(PIN_LCD_RST, OUTPUT);
895	  digitalWrite(PIN_LCD_RST, HIGH);
896	  delay(50);
897	  digitalWrite(PIN_LCD_RST, LOW);
898	  delay(100);
899	  digitalWrite(PIN_LCD_RST, HIGH);
900	  delay(150);
901	
902	  tft.init();
903	  tft.setRotation(1);
904	  tft.setBrightness(255);
905	  tft.fillScreen(C_BLACK);
906	
907	  fIT13.init(FONT_IT13); fBD13.init(FONT_BD13); fRG11.init(FONT_RG11);
908	  fRG10.init(FONT_RG10); fSB10.init(FONT_SB10); fSB9.init(FONT_SB9);
909	  Serial.println("Fonts initialized");
910	
911	  delay(300);
912	
913	  Serial.println("Showing splash screen...");
914	  splash("RIEN-PRESCRIPT-BEEPER", "MODEL 01-ORACLE");
915	  delay(900);
916	
917	  if (strlen(WIFI_SSID) > 0 || MOBILE_HOTSPOT_ENABLED) {
918	    splash("Connecting Wi-Fi...", "Mobile Hotspot Priority");
919	    WiFi.mode(WIFI_STA);
920	    delay(100);  // Let STA mode settle before touching RF config
921	    WiFi.setTxPower(WIFI_POWER_19_5dBm);  // Max TX power — best chance of association
922	    WiFi.setSleep(false);                 // Disable modem sleep for stable initial connection
923	
924	    // Use mobile hotspot priority connection system
925	    if (connectToWifiWithPriority()) {
926	      Serial.printf("[wifi] Connected: %s\n", WiFi.localIP().toString().c_str());
927	      splash("Syncing prescripts...", "Cloudflare Edge");
928	      fetchQuotes();
929	    } else {
930	      splash("Wi-Fi unavailable", "Offline standby");
931	      delay(1000);
932	    }
933	  } else {
934	    Serial.println("[wifi] no SSID configured -> offline standby");
935	  }
936	
937	  if (quotes.empty()) {
938	    setOfflineStandbyQuote();
939	  }
940	
941	  loadQuote(0, true, true);
942	}
943	
944	void loop() {
945	  // Serial command interface for remote manual triggering
946	  if (Serial.available()) {
947	    char ch = Serial.read();
948	    if (ch == 'r' || ch == 'R') {
949	      Serial.println("[SIM] ROLL trigger");
950	      rollQuote();
951	      return;
952	    }
953	    if (ch == 's' || ch == 'S' || ch == 'p' || ch == 'P') {
954	      Serial.println("[SIM] SCROLL / PAGE trigger");
955	      changePage();
956	      return;
957	    }
958	    if (ch == 'c' || ch == 'C' || ch == 'w' || ch == 'W') {
959	      Serial.println("[SIM] CLOUD RE-SYNC trigger");
960	      if (WiFi.status() != WL_CONNECTED) {
961	        Serial.printf("[wifi] Connecting to %s...\n", WIFI_SSID);
962	        WiFi.begin(WIFI_SSID, WIFI_PASS);
963	        uint32_t t0 = millis();
964	        while (WiFi.status() != WL_CONNECTED && millis() - t0 < 8000) delay(200);
965	      }
966	      if (WiFi.status() == WL_CONNECTED) {
967	        Serial.printf("[wifi] Connected: %s\n", WiFi.localIP().toString().c_str());
968	        fetchQuotes();
969	      } else {
970	        Serial.printf("[wifi] Status: %d\n", WiFi.status());
971	      }
972	      return;
973	    }
974	  }
975	
976	  // Physical button checks (100% manual control)
977	  if (btnRoll.pressed() || btnRollAlt.pressed()) {
978	    Serial.println("[btn] ROLL");
979	    rollQuote();
980	    return;
981	  }
982	  if (btnScroll.pressed()) {
983	    Serial.println("[btn] SCROLL");
984	    changePage();
985	    return;
986	  }
987	
988	  if (animating) {
989	    stepAnimation();
990	  } else if (WiFi.status() == WL_CONNECTED) {
991	    // Background cloud sync every 15 minutes when idle
992	    static uint32_t lastApiRefresh = 0;
993	    if (millis() - lastApiRefresh > 15UL * 60 * 1000) {
994	      lastApiRefresh = millis();
995	      fetchQuotes();
996	    }
997	  }
998	
999	  // Pure manual mode: NO auto-page, NO auto-reroll!
1000	  delay(1);
1001	}
